// domain-watcher — fetch RDAP, diff vs stored state, emit alert lines.
// State persists in n8n staticData (postgres). Source of truth:
// ~/git/homeserver-apps/domain-watcher/workflow/domain-watcher.n8n.json
const WATCHLIST = [
  'adept.dev',            // lost to a drop-catcher 2026-10-10; parked on atom — watch for re-drop
  'adeptproductions.com', // dormant since 2005, renewed to 2028 — watch for lapse
  'adeptproductions.dev', // OWNED — renewal safety net
  'adeptofficial.dev',    // fallback name — alert if someone takes it
  'adeptlab.dev',         // OWNED — infra-critical
];
const PARKING = /(atom|sedo|afternic|dan|parkingcrew|bodis|squadhelp|hugedomains)\./i;

const sd = $getWorkflowStaticData('global');
sd.domains = sd.domains || {};
const firstRun = !sd.initialized;
const alerts = [];
const baseline = [];

for (const d of WATCHLIST) {
  let snap;
  try {
    const res = await this.helpers.httpRequest({
      url: `https://rdap.org/domain/${d}`,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: true,
      timeout: 20000,
      headers: { accept: 'application/rdap+json, application/json' },
    });
    const code = res.statusCode;
    if (code === 404) {
      snap = { available: true, error: false, status: [], expiry: null, ns: [], registrar: null };
    } else if (code >= 200 && code < 300) {
      const b = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
      const exp = (b.events || []).find((e) => e.eventAction === 'expiration');
      const reg = (b.entities || []).find((e) => (e.roles || []).includes('registrar'));
      const fn = reg && reg.vcardArray && reg.vcardArray[1]
        ? (reg.vcardArray[1].find((x) => x[0] === 'fn') || [])[3] : null;
      snap = {
        available: false, error: false,
        status: (b.status || []).slice().sort(),
        expiry: exp ? String(exp.eventDate).slice(0, 10) : null,
        ns: (b.nameservers || []).map((n) => String(n.ldhName || '').toLowerCase()).sort(),
        registrar: fn || null,
      };
    } else {
      snap = { available: false, error: true, status: [], expiry: null, ns: [], registrar: null };
    }
  } catch (e) {
    snap = { available: false, error: true, status: [], expiry: null, ns: [], registrar: null };
  }

  const prev = sd.domains[d];
  const L = `**${d}**`;
  if (!prev) {
    baseline.push(
      `• ${d}: ` +
      (snap.error ? 'fetch error' : snap.available ? 'AVAILABLE' :
        `expires ${snap.expiry || '?'}${snap.registrar ? ' · ' + snap.registrar : ''}`)
    );
  } else {
    if (prev.error !== snap.error) {
      alerts.push(snap.error ? `⚠️ ${L}: RDAP lookups failing` : `✅ ${L}: RDAP lookups recovered`);
    }
    if (!snap.error && !prev.error) {
      const sj = (a) => JSON.stringify(a);
      if (prev.available !== snap.available) {
        alerts.push(snap.available
          ? `🟢 ${L} IS AVAILABLE — GRAB IT NOW <@__PING_ID__>`
          : `🔒 ${L} just got registered by someone`);
      }
      if (sj(prev.status) !== sj(snap.status)) {
        const drop = snap.status.some((s) => /pending ?delete|redemption/i.test(s));
        alerts.push(`${drop ? '🚨' : 'ℹ️'} ${L} status: [${prev.status}] → [${snap.status}]` +
          (drop ? ' — DROP INCOMING, place backorders NOW <@__PING_ID__>' : ''));
      }
      if (sj(prev.ns) !== sj(snap.ns)) {
        const park = snap.ns.some((n) => PARKING.test(n));
        alerts.push(`${park ? '🅿️' : '🔀'} ${L} nameservers: ${prev.ns.join(', ') || '—'} → ${snap.ns.join(', ') || '—'}` +
          (park ? ' (parking service — likely listed for sale)' : ''));
      }
      if (prev.registrar !== snap.registrar) {
        alerts.push(`🏷️ ${L} registrar: ${prev.registrar || '—'} → ${snap.registrar || '—'}`);
      }
      if (prev.expiry !== snap.expiry) {
        alerts.push(`📅 ${L} expiry moved: ${prev.expiry || '—'} → ${snap.expiry || '—'}`);
      }
    }
  }

  // Expiry proximity warnings at 30/14/7/1 days — each threshold fires once.
  snap.warned = prev ? (prev.warned ?? null) : null;
  if (!snap.error && snap.expiry) {
    const days = Math.floor((Date.parse(snap.expiry) - Date.now()) / 86400000);
    const th = [1, 7, 14, 30].find((t) => days <= t) ?? null;
    if (th !== null && th !== snap.warned) {
      alerts.push(`⏳ ${L} expires in ${days} day(s) — ${snap.expiry}`);
      snap.warned = th;
    }
    if (days > 30) snap.warned = null;
  }

  sd.domains[d] = snap;
}

if (firstRun) {
  sd.initialized = true;
  alerts.unshift('🛰️ **domain-watcher armed** — baseline:\n' + baseline.join('\n'));
}

if (alerts.length === 0) return [];
let content = alerts.join('\n');
if (content.length > 1900) content = content.slice(0, 1900) + '\n…(truncated)';
return [{ json: { content } }];
